213: 
214:   proto.play = function () {
215:     const s = getState(this);
216:     s.paused = false;
217:     s.ended = false;
218:     s.readyState = 4;
219:     this.dispatchEvent(new window.Event('play'));
220:     this.dispatchEvent(new window.Event('playing'));
221:     return Promise.resolve();
222:   };
223: 
224:   proto.pause = function () {
