254: 
255:   // Simulation test helpers
256:   proto._simulateTimeUpdate = function (t) {
257:     const s = getState(this);
258:     s.currentTime = Math.max(0, Math.min(s.duration, t));
259:     this.dispatchEvent(new window.Event('timeupdate'));
260:   };
261: 
262:   proto._simulateProgress = function (endSec) {
