282:     s.paused = true;
283:     this.dispatchEvent(new window.Event('ended'));
284:   };
285: 
286:   proto._simulateError = function (code, message) {
287:     getState(this).error = { code: code || 4, message: message || 'Media Error' };
288:     this.dispatchEvent(new window.Event('error'));
289:   };
290: }
