295: ### 3.2 Mock Hls.js Simulation Engine (`window.Hls`)
296: The test environment simulates the full HLS.js streaming lifecycle and event bus without external dependencies.
297: 
298: #### Properties & Configuration:
299: - `config`: Verified against webOS 1.5GB RAM limits (`maxBufferSize: 30 * 1024 * 1024`, `maxBufferLength: 30`, `liveSyncDurationCount: 3`).
300: - `levels`: Array of quality ladders (`360p`, `720p`, `1080p`, `4K`).
301: - `currentLevel`: Getter/setter for quality switching.
302: - `subtitleTracks`: Array of subtitle track objects.
303: - `subtitleTrack`: Getter/setter for active subtitle index (-1 for disabled).
304: - `destroyed`: Boolean flag tracking resource cleanup.
305: 
306: #### Event Constants & Enums:
307: - `Hls.isSupported()` returns `true`.
308: - `Hls.Events`: `MANIFEST_LOADING`, `MANIFEST_LOADED`, `MANIFEST_PARSED`, `LEVEL_LOADED`, `FRAG_LOADING`, `FRAG_LOADED`, `ERROR`, `MEDIA_ATTACHED`, `MEDIA_DETACHED`, `SUBTITLE_TRACKS_UPDATED`, `SUBTITLE_TRACK_SWITCH`.
309: - `Hls.ErrorTypes`: `NETWORK_ERROR`, `MEDIA_ERROR`, `KEY_SYSTEM_ERROR`, `MUX_ERROR`, `OTHER_ERROR`.
310: - `Hls.ErrorDetails`: `MANIFEST_LOAD_ERROR`, `MANIFEST_LOAD_TIMEOUT`, `BUFFER_STALLED_ERROR`, `FRAG_LOAD_ERROR`, `LEVEL_LOAD_ERROR`, `INTERNAL_EXCEPTION`.
311: 
312: ```javascript
313: function installHlsMock(window) {
314:   function MockHls(config) {
315:     this.config = config || {};
316:     this.media = null;
317:     this.url = null;
318:     this.destroyed = false;
319:     this._listeners = {};
320: 
321:     this.levels = [
322:       { bitrate: 800000, width: 640, height: 360, name: '360p' },
323:       { bitrate: 2500000, width: 1280, height: 720, name: '720p' },
324:       { bitrate: 5000000, width: 1920, height: 1080, name: '1080p' },
325:       { bitrate: 15000000, width: 3840, height: 2160, name: '4K' }
326:     ];
327:     this._currentLevel = -1;
328: 
329:     this.subtitleTracks = [
330:       { id: 0, lang: 'en', name: 'English' },
331:       { id: 1, lang: 'es', name: 'Spanish' }
332:     ];
333:     this._subtitleTrack = -1;
334:   }
335: 
336:   Object.defineProperty(MockHls.prototype, 'currentLevel', {
337:     get: function () { return this._currentLevel; },
338:     set: function (lvl) {
339:       this._currentLevel = lvl;
340:       this.trigger(MockHls.Events.LEVEL_LOADED, { level: lvl });
341:     }
342:   });
343: 
344:   Object.defineProperty(MockHls.prototype, 'subtitleTrack', {
345:     get: function () { return this._subtitleTrack; },
346:     set: function (trackId) {
347:       this._subtitleTrack = trackId;
348:       this.trigger(MockHls.Events.SUBTITLE_TRACK_SWITCH, { id: trackId });
349:     }
350:   });
351: 
352:   MockHls.prototype.on = function (event, cb) {
353:     if (!this._listeners[event]) this._listeners[event] = [];
354:     this._listeners[event].push(cb);
355:   };
356: 
357:   MockHls.prototype.off = function (event, cb) {
358:     if (!this._listeners[event]) return;
359:     this._listeners[event] = this._listeners[event].filter(function (fn) { return fn !== cb; });
360:   };
361: 
362:   MockHls.prototype.trigger = function (event, data) {
363:     const list = this._listeners[event] || [];
364:     for (let i = 0; i < list.length; i++) {
365:       try { list[i](event, data || {}); } catch (err) { console.error('HLS trigger error:', err); }
366:     }
367:   };
368: 
369:   MockHls.prototype.attachMedia = function (mediaElement) {
370:     this.media = mediaElement;
371:     this.trigger(MockHls.Events.MEDIA_ATTACHED, { media: mediaElement });
372:   };
373: 
374:   MockHls.prototype.loadSource = function (url) {
375:     this.url = url;
376:     this.trigger(MockHls.Events.MANIFEST_LOADING, { url });
377:     const self = this;
378:     setTimeout(function () {
379:       if (!self.destroyed) {
380:         self.trigger(MockHls.Events.MANIFEST_LOADED, { url, levels: self.levels });
381:         self.trigger(MockHls.Events.MANIFEST_PARSED, { levels: self.levels });
382:       }
383:     }, 10);
384:   };
385: 
386:   MockHls.prototype.startLoad = function (startPosition) {
387:     this.startPosition = startPosition;
388:     this.loading = true;
389:   };
390: 
391:   MockHls.prototype.stopLoad = function () {
392:     this.loading = false;
393:   };
394: 
395:   MockHls.prototype.recoverMediaError = function () {
396:     this._recoveredMediaErrors = (this._recoveredMediaErrors || 0) + 1;
397:   };
398: 
399:   MockHls.prototype.destroy = function () {
