513:       width: width,
514:       height: height,
515:       right: left + width,
516:       bottom: top + height,
517:       x: left,
518:       y: top
519:     };
520:   }
521: 
522:   window.Element.prototype.getBoundingClientRect = function () {
523:     if (this.style.display === 'none') return makeRect(0, 0, 0, 0);
524: 
525:     const id = this.id;
526:     // Top Bar
527:     if (id === 'player-back-btn') return makeRect(96, 54, 54, 54);
528:     if (id === 'osd-title') return makeRect(174, 54, 800, 40);
