/* ==========================================================================
   10-Foot Fullscreen Player Container & Safe Area Overlay
   ========================================================================== */
.player-container {
  position: absolute;
  inset: 0;
  width: 1920px;
  height: 1080px;
  background-color: var(--color-bg-black); /* #000000 */
  z-index: 200;
  overflow: hidden;
  user-select: none;
}

.player-container.idle-cursor,
.player-container.idle-cursor * {
  cursor: none !important;
}

.player-video {
  width: 100%;
  height: 100%;
  object-fit: contain;
  background-color: #000000;
}

/* ==========================================================================
   OSD HUD Vignette & Fade Transition
   ========================================================================== */
.player-osd {
  position: absolute;
  inset: 0;
  z-index: 210;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: var(--tv-safe-y) var(--tv-safe-x); /* 54px top/bottom, 96px left/right */
  background: 
    linear-gradient(180deg, rgba(0, 0, 0, 0.88) 0%, rgba(0, 0, 0, 0.45) 160px, rgba(0, 0, 0, 0) 240px),
    linear-gradient(0deg, rgba(0, 0, 0, 0.94) 0%, rgba(0, 0, 0, 0.60) 220px, rgba(0, 0, 0, 0) 320px);
  transition: opacity 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  pointer-events: auto;
  opacity: 1;
}

.player-osd.osd-hidden {
  opacity: 0 !important;
  pointer-events: none !important;
}

/* ==========================================================================
   Top Bar Tier
   ========================================================================== */
.osd-top-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 64px;
}

.osd-title-group {
  display: flex;
  align-items: center;
  gap: 18px;
}

.osd-title-stack {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.osd-title {
  font-family: var(--font-family-headings);
  font-size: var(--font-size-h2); /* 28px */
  font-weight: var(--font-weight-bold);
  color: #FFFFFF;
  margin: 0;
  line-height: var(--line-height-tight);
}

.osd-meta-episode {
  font-size: var(--font-size-body); /* 18px */
  font-weight: var(--font-weight-medium);
  color: var(--color-accent-primary); /* #95FF50 */
}

/* ==========================================================================
   Bottom Bar Tier: Scrubber Timeline
   ========================================================================== */
.osd-bottom-bar {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.osd-progress-wrapper {
  display: flex;
  align-items: center;
  gap: 22px;
  width: 100%;
}

.osd-time {
  font-family: var(--font-family-base);
  font-size: 18px;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-secondary);
  font-variant-numeric: tabular-nums;
  min-width: 80px;
  text-align: center;
  letter-spacing: 0.5px;
}

.osd-progress-track {
  flex: 1;
  height: 10px;
  background-color: rgba(255, 255, 255, 0.22);
  border-radius: var(--radius-pill);
  position: relative;
  outline: none;
  cursor: pointer;
  transition: height 0.2s cubic-bezier(0.4, 0, 0.2, 1), transform 0.2s ease;
}

.osd-progress-track.focused,
.osd-progress-track[data-nav="true"].focused {
  height: 14px;
  box-shadow: 0 0 20px rgba(149, 255, 80, 0.65);
}

.osd-buffer-fill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 0%;
  background-color: rgba(255, 255, 255, 0.42);
  border-radius: var(--radius-pill);
  transition: width 0.25s linear;
}

.osd-progress-fill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 0%;
  background-color: var(--color-accent-primary); /* #95FF50 */
  border-radius: var(--radius-pill);
  box-shadow: 0 0 14px var(--color-accent-glow);
}

.osd-scrub-thumb {
  position: absolute;
  top: 50%;
  left: 0%;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background-color: #FFFFFF;
  border: 3px solid var(--color-accent-primary);
  box-shadow: 0 0 16px var(--color-accent-glow);
  transform: translate(-50%, -50%);
  transition: transform 0.2s ease, width 0.2s ease, height 0.2s ease;
  pointer-events: none;
}

.osd-progress-track.focused .osd-scrub-thumb {
  width: 26px;
  height: 26px;
  border-width: 4px;
  transform: translate(-50%, -50%) scale(1.15);
}

/* ==========================================================================
   Action Controls Row
   ========================================================================== */
.osd-controls-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 72px;
}

.osd-controls-main {
  display: flex;
  align-items: center;
  gap: 24px;
}

.osd-controls-aux {
  display: flex;
  align-items: center;
  gap: 16px;
}

.osd-btn {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  background-color: rgba(255, 255, 255, 0.12);
  border: 1px solid var(--color-border-card);
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  outline: none;
  position: relative;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.osd-btn .btn-subscript {
  position: absolute;
  bottom: 8px;
  font-size: 10px;
  font-weight: var(--font-weight-bold);
  color: #FFFFFF;
  line-height: 1;
}

.osd-btn.btn-play-pause {
  width: 68px;
  height: 68px;
  background-color: var(--color-accent-primary); /* #95FF50 */
  color: #04120B;
  border: none;
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.4);
}

.osd-btn.btn-play-pause svg {
  width: 32px;
  height: 32px;
  fill: #04120B;
}

.osd-pill-btn {
  width: auto;
  height: 52px;
  padding: 0 22px;
  border-radius: var(--radius-pill);
  gap: 10px;
  font-size: var(--font-size-body);
  font-weight: var(--font-weight-medium);
}

/* ==========================================================================
   Focus State Indicators (Spatial Remote Navigation)
   ========================================================================== */
.osd-btn[data-nav="true"].focused,
.osd-btn.focused {
  background-color: rgba(149, 255, 80, 0.35) !important;
  border-color: #95FF50 !important;
  box-shadow: 0 0 28px rgba(149, 255, 80, 0.85) !important;
  transform: scale(1.15) !important;
  color: #FFFFFF !important;
}

.osd-btn.btn-play-pause[data-nav="true"].focused,
.osd-btn.btn-play-pause.focused {
  background-color: #B4FF78 !important;
  box-shadow: 0 0 36px rgba(149, 255, 80, 0.95) !important;
  transform: scale(1.18) !important;
}

/* ==========================================================================
   Buffering Spinner Overlay
   ========================================================================== */
.player-buffering-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  z-index: 208;
  background-color: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(4px);
}

.buffering-spinner {
  width: 64px;
  height: 64px;
  border: 5px solid rgba(255, 255, 255, 0.18);
  border-top-color: var(--color-accent-primary);
  border-radius: 50%;
  animation: spin 0.9s linear infinite;
}

.buffering-text {
  font-size: 22px;
  color: #FFFFFF;
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.5px;
}

/* ==========================================================================
   10-Foot Modal Cards (Error, Subtitles, Server Selection)
   ========================================================================== */
.player-modal-backdrop {
  position: absolute;
  inset: 0;
  z-index: 250;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(12px);
}

.player-modal-card {
  width: 640px;
  max-height: 800px;
  background-color: var(--color-surface-modal); /* rgba(20, 24, 22, 0.96) */
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 20px;
  padding: 36px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.85);
}

.player-modal-card.error-card {
  width: 600px;
  text-align: center;
  align-items: center;
}

.player-modal-title {
  font-family: var(--font-family-headings);
  font-size: 28px;
  font-weight: var(--font-weight-bold);
  color: #FFFFFF;
  margin: 0;
}

.player-modal-desc {
  font-size: 20px;
  line-height: var(--line-height-normal);
  color: var(--color-text-secondary);
  margin: 0;
}

.player-modal-actions {
  display: flex;
  gap: 16px;
  width: 100%;
  justify-content: center;
  margin-top: 12px;
}

.modal-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.osd-btn-close {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.modal-card-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-height: 480px;
  overflow-y: auto;
  padding-right: 8px;
}

.modal-list-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 20px;
  background-color: rgba(255, 255, 255, 0.06);
  border: 2px solid transparent;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.modal-list-item.focused,
.modal-list-item[data-nav="true"].focused {
  background-color: rgba(149, 255, 80, 0.25) !important;
  border-color: #95FF50 !important;
  box-shadow: 0 0 20px rgba(149, 255, 80, 0.6) !important;
  transform: scale(1.02) !important;
}

.modal-list-item .track-name {
  font-size: 20px;
  color: #FFFFFF;
  font-weight: var(--font-weight-medium);
}

.modal-list-item.active .track-name {
  color: var(--color-accent-primary);
  font-weight: var(--font-weight-bold);
}

.modal-list-item .track-active-check {
  font-size: 22px;
  color: var(--color-accent-primary);
  display: none;
}

.modal-list-item.active .track-active-check {
  display: inline-block;
}

/* ==========================================================================
   Visual Feedback Seek Toast (+/-10s)
   ========================================================================== */
.player-feedback-toast {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 220;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px 36px;
  background-color: rgba(14, 18, 16, 0.92);
  border: 1px solid var(--color-accent-primary);
  border-radius: var(--radius-pill);
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.7), 0 0 24px rgba(149, 255, 80, 0.4);
  font-size: 22px;
  font-weight: var(--font-weight-bold);
  color: #FFFFFF;
  pointer-events: none;
  animation: toastFade 1.2s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

@keyframes toastFade {
  0% { opacity: 0; transform: translate(-50%, -40%) scale(0.9); }
  15% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  80% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -55%) scale(0.95); }
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

