/**
 * Handle remote control media keys
 */
handleMediaKey: function (action) {
  if (this.state.currentView === 'player' && global.PlayerController) {
    switch (action) {
      case 'MEDIA_PLAY':
        global.PlayerController.play();
        if (global.PlayerOSDController) global.PlayerOSDController.resetIdleTimer();
        return;
      case 'MEDIA_PAUSE':
        global.PlayerController.pause();
        if (global.PlayerOSDController) global.PlayerOSDController.showHUD();
        return;
      case 'MEDIA_PLAY_PAUSE':
        global.PlayerController.togglePlayPause();
        return;
      case 'MEDIA_STOP':
        this.exitPlayer();
        return;
      case 'MEDIA_FAST_FORWARD':
        global.PlayerController.seek(10);
        if (global.PlayerOSDController) global.PlayerOSDController.showSeekFeedback(true, 10);
        return;
      case 'MEDIA_REWIND':
        global.PlayerController.seek(-10);
        if (global.PlayerOSDController) global.PlayerOSDController.showSeekFeedback(false, 10);
        return;
    }
  }

  var video = document.getElementById('main-video-player');
  if (!video) return;

  switch (action) {
    case 'MEDIA_PLAY':
      try { video.play(); } catch (_) {}
      break;
    case 'MEDIA_PAUSE':
      try { video.pause(); } catch (_) {}
      break;
    case 'MEDIA_PLAY_PAUSE':
      try {
        if (video.paused) video.play();
        else video.pause();
      } catch (_) {}
      break;
    case 'MEDIA_STOP':
      try { video.pause(); } catch (_) {}
      this.exitPlayer();
      break;
    case 'MEDIA_FAST_FORWARD':
      try { video.currentTime = Math.min(video.duration || Infinity, video.currentTime + 10); } catch (_) {}
      break;
    case 'MEDIA_REWIND':
      try { video.currentTime = Math.max(0, video.currentTime - 10); } catch (_) {}
      break;
  }
},

