/**
 * Cinejoy webOS - Media Player Engine & 10-Foot TV Playback Overlay
 * File: app/js/player.js
 * Standard: 10-Foot Television UX, webOS 8.5.0 (Chromium ~108+)
 * Target Device: LG 32LR686BPSA (1920x1080 Full HD Canvas)
 * 
 * Incorporates:
 * - window.PlayerController: Core playback engine, Hls.js low-memory profile,
 *   proxy stream resolution, multi-server fallback, WebVTT subtitle ingestion,
 *   resume position tracking, and 5-stage deterministic teardown.
 * - window.PlayerOSDController: 10-foot TV HUD overlay, 4000ms auto-hide timer,
 *   timeline scrubber, remote key mappings, subtitle/server modal dialogs,
 *   buffering spinner, and error recovery.
 */

(function (global) {
  'use strict';

  // ===========================================================================
  // 1. Constants & Configuration
  // ===========================================================================

  var CLUSTER_SERVERS = ['secret', 'Nebula', 'Lisbon', 'Solara', 'Athens'];

  var HLS_WEBOS_CONFIG = {
    // webOS Low-Memory Buffer Bounds (1.5GB Physical RAM safety)
    maxBufferLength: 15,
    maxMaxBufferLength: 25,
    maxBufferSize: 20 * 1024 * 1024, // 20 MB ceiling
    backBufferLength: 10,            // Evict segments older than 10s behind playhead
    maxBufferHole: 0.5,

    // VOD Fragmented MP4 Optimizations
    lowLatencyMode: false,
    enableWorker: true,
    progressive: false,

    // ABR Bandwidth Safeguards
    startLevel: -1,
    abrEwmaDefaultEstimate: 5000000,
    abrBandWidthFactor: 0.85,
    abrBandWidthUpFactor: 0.7,
    abrMaxWithRealBitrate: true,

    // Network Timeouts & Retries
    manifestLoadingTimeOut: 15000,
    manifestLoadingMaxRetry: 3,
    manifestLoadingRetryDelay: 1000,
    levelLoadingTimeOut: 15000,
    levelLoadingMaxRetry: 3,
    levelLoadingRetryDelay: 1000,
    fragLoadingTimeOut: 20000,
    fragLoadingMaxRetry: 4,
    fragLoadingRetryDelay: 1000,

    autoStartLoad: true
  };

  /**
   * Format raw seconds into zero-padded HH:MM:SS string.
   * @param {number} totalSeconds
   * @returns {string} Zero-padded HH:MM:SS
   */
  function formatTime(totalSeconds) {
    if (typeof totalSeconds !== 'number' || isNaN(totalSeconds) || totalSeconds < 0 || !isFinite(totalSeconds)) {
      return '00:00:00';
    }
    var sec = Math.floor(totalSeconds);
    var hours = Math.floor(sec / 3600);
    var minutes = Math.floor((sec % 3600) / 60);
    var seconds = sec % 60;

    var hStr = hours < 10 ? '0' + hours : String(hours);
    var mStr = minutes < 10 ? '0' + minutes : String(minutes);
    var sStr = seconds < 10 ? '0' + seconds : String(seconds);

    return hStr + ':' + mStr + ':' + sStr;
  }

  /**
   * Compute normalized localStorage key for playback resume position.
   */
  function getPlaybackStorageKey(tmdbId, type, season, episode) {
    var mType = (type === 'tv' || type === 'series') ? 'tv' : 'movie';
    if (mType === 'tv') {
      return 'cinejoy_playback_' + tmdbId + '_tv_' + (season || 1) + '_' + (episode || 1);
    }
    return 'cinejoy_playback_' + tmdbId + '_movie';
  }

  // ===========================================================================
  // 2. PlayerController Core Engine
  // ===========================================================================

  var PlayerController = {
    initialized: false,
    video: null,
    videoElement: null,
    hls: null,
    state: 'IDLE', // IDLE, RESOLVING, LOADING, READY, PLAYING, PAUSED, BUFFERING, ENDED, ERROR
    streamUrl: null,
    originalUrl: null,
    currentItem: null,
    activeServer: 'secret',
    qualityLevels: [],
    audioTracks: [],
    subtitleTracks: [],
    subtitles: [],
    duration: 0,
    currentTime: 0,
    bufferedTime: 0,
    isBuffering: false,
    _listeners: {},
    _abortController: null,
    _streamTimeoutTimer: null,
    _resumeSaveTimer: null,
    _targetResumeTime: null,
    _videoListeners: {},
    _customProxyBaseUrl: null,

    /**
     * Initialize PlayerController DOM bindings and events. Idempotent.
     */
    init: function (options) {
      if (this.initialized) {
        if (options && options.videoElement) {
          this.video = options.videoElement;
          this.videoElement = options.videoElement;
        }
        return;
      }
      this.initialized = true;
      this.state = 'IDLE';

      var opts = options || {};
      if (opts.proxyBaseUrl) {
        this._customProxyBaseUrl = opts.proxyBaseUrl;
      }

      var videoEl = opts.videoElement || (typeof document !== 'undefined' ? document.getElementById('main-video-player') : null);
      this.video = videoEl;
      this.videoElement = videoEl;

      if (global.PlayerOSDController && typeof global.PlayerOSDController.init === 'function') {
        global.PlayerOSDController.init(opts);
      }

      console.log('[PlayerController] Initialized in state IDLE');
    },

    /**
     * Subscribe to player event.
     */
    on: function (event, fn) {
      if (typeof fn !== 'function') return;
      if (!this._listeners[event]) this._listeners[event] = [];
      this._listeners[event].push(fn);
    },

    /**
     * Unsubscribe from player event.
     */
    off: function (event, fn) {
      var list = this._listeners[event];
      if (!list) return;
      this._listeners[event] = list.filter(function (cb) { return cb !== fn; });
    },

    /**
     * Emit player event.
     */
    emit: function (event, data) {
      var list = this._listeners[event];
      if (list && list.length) {
        for (var i = 0; i < list.length; i++) {
          try {
            list[i](data);
          } catch (err) {
            console.error('[PlayerController] Error in listener for ' + event + ':', err);
          }
        }
      }
    },

    /**
     * Set state and emit statechange event.
     */
    _setState: function (newState) {
      var prev = this.state;
      if (prev === newState) return;
      this.state = newState;
      this.emit('statechange', { state: newState, previousState: prev });
    },

    /**
     * Primary entry point: Resolves stream from proxy, attaches Hls, and starts playback.
     */
    loadStream: function (itemPayload, serverOverride) {
      var self = this;
      this.init();

      if (!itemPayload) {
        var errMissing = new Error('RESOLVE_INVALID_ID: Missing playback item payload');
        this.handleFatalError('RESOLVE_INVALID_ID', errMissing.message);
        return Promise.reject(errMissing);
      }

      var tmdbId = itemPayload.tmdbId || itemPayload.id;
      if (!tmdbId) {
        var errId = new Error('RESOLVE_INVALID_ID: Missing tmdbId in playback item payload');
        this.handleFatalError('RESOLVE_INVALID_ID', errId.message);
        return Promise.reject(errId);
      }

      this.currentItem = itemPayload;
      var targetServer = serverOverride || itemPayload.server || 'secret';
      this.activeServer = targetServer;

      // Teardown any running HLS / video state before loading new stream
      this._stopPlaybackPipeline();

      this._setState('RESOLVING');
      if (global.PlayerOSDController) {
        global.PlayerOSDController.setContentInfo({
          title: itemPayload.title || itemPayload.name || 'Title',
          season: itemPayload.season,
          episode: itemPayload.episode,
          format: 'HLS fMP4',
          server: targetServer
        });
        global.PlayerOSDController.setBuffering(true, 'Connecting stream...');
      }

      // Check for saved resume position in localStorage
      var savedResume = this._getSavedResumeRecord(itemPayload);
      if (savedResume && savedResume.position > 10) {
        this._targetResumeTime = savedResume.position;
        this.emit('resumeposition', { position: savedResume.position, duration: savedResume.duration });
      } else {
        this._targetResumeTime = null;
      }

      // 15-second stream startup watchdog
      this._clearStreamWatchdog();
      this._streamTimeoutTimer = setTimeout(function () {
        if (self.state === 'RESOLVING' || self.state === 'LOADING' || self.state === 'BUFFERING') {
          self.handleFatalError('STREAM_TIMEOUT', 'Stream connection timed out after 15 seconds.');
        }
      }, 15000);

      return this._resolveStreamWithFallback(itemPayload, targetServer, 0)
        .then(function (streamData) {
          return self._attachAndPlayStream(streamData);
        })
        .catch(function (err) {
          self._clearStreamWatchdog();
          self.handleFatalError('RESOLVE_FAIL', err.message || 'Failed to resolve stream');
          throw err;
        });
    },

    // Alias for loadStream
    loadMedia: function (itemPayload, serverOverride) {
      return this.loadStream(itemPayload, serverOverride);
    },

    /**
     * Resolve stream from local proxy with multi-server cascade fallback.
     */
    _resolveStreamWithFallback: function (itemPayload, preferredServer, fallbackIndex) {
      var self = this;
      var serverToTry = preferredServer;
      if (fallbackIndex > 0) {
        var altList = CLUSTER_SERVERS.filter(function (s) { return s !== preferredServer; });
        serverToTry = altList[fallbackIndex - 1];
        if (!serverToTry) {
          return Promise.reject(new Error('All server fallbacks exhausted'));
        }
      }

      return this._fetchStreamResolution(itemPayload, serverToTry).catch(function (err) {
        console.warn('[PlayerController] Server ' + serverToTry + ' failed:', err.message);
        if (fallbackIndex < CLUSTER_SERVERS.length - 1) {
          console.log('[PlayerController] Attempting fallback cascade index ' + (fallbackIndex + 1) + '...');
          return self._resolveStreamWithFallback(itemPayload, preferredServer, fallbackIndex + 1);
        }
        throw err;
      });
    },

    /**
     * Query /api/stream endpoint on local proxy.
     */
    _fetchStreamResolution: function (itemPayload, serverName) {
      var self = this;
      var baseUrl = this._customProxyBaseUrl ||
                    (typeof window !== 'undefined' && window.CINEJOY_CONFIG && window.CINEJOY_CONFIG.proxyBaseUrl) ||
                    'http://127.0.0.1:8088';

      var mediaType = (itemPayload.type === 'tv' || itemPayload.media_type === 'tv') ? 'tv' : 'movie';
      var tmdbId = itemPayload.tmdbId || itemPayload.id;

      var params = [];
      params.push('tmdbId=' + encodeURIComponent(String(tmdbId)));
      params.push('type=' + encodeURIComponent(mediaType));
      if (mediaType === 'tv') {
        params.push('season=' + encodeURIComponent(String(itemPayload.season || 1)));
        params.push('episode=' + encodeURIComponent(String(itemPayload.episode || 1)));
      }
      params.push('server=' + encodeURIComponent(serverName || 'secret'));

      var url = baseUrl + '/api/stream?' + params.join('&');

      if (typeof AbortController !== 'undefined') {
        this._abortController = new AbortController();
      }

      var timeoutId = null;
      var fetchPromise;

      if (typeof fetch === 'function') {
        var fetchOpts = {
          method: 'GET',
          headers: { 'Accept': 'application/json' }
        };
        if (this._abortController) {
          fetchOpts.signal = this._abortController.signal;
        }

        timeoutId = setTimeout(function () {
          if (self._abortController) {
            try { self._abortController.abort(); } catch (_) {}
          }
        }, 12000);

        fetchPromise = fetch(url, fetchOpts);
      } else {
        return Promise.reject(new Error('Fetch API unavailable'));
      }

      return fetchPromise.then(function (response) {
        if (timeoutId) clearTimeout(timeoutId);
        if (!response.ok) {
          return response.text().then(function (text) {
            throw new Error('Proxy HTTP ' + response.status + ': ' + text);
          });
        }
        return response.json();
      }).then(function (data) {
        if (!data || !data.success || !data.streamUrl) {
          throw new Error('RESOLVE_NO_STREAM: Stream URL not present in proxy response');
        }
        return {
          streamUrl: data.streamUrl,
          originalUrl: data.originalUrl,
          server: data.server || serverName,
          subtitles: Array.isArray(data.subtitles) ? data.subtitles : []
        };
      }).catch(function (err) {
        if (timeoutId) clearTimeout(timeoutId);
        if (err.name === 'AbortError') {
          throw new Error('RESOLVE_TIMEOUT: Stream resolution timed out after 12s');
        }
        throw err;
      });
    },

    /**
     * Attach stream URL to HLS.js or native HTML5 video element.
     */
    _attachAndPlayStream: function (streamData) {
      var self = this;
      this.streamUrl = streamData.streamUrl;
      this.originalUrl = streamData.originalUrl;
      this.activeServer = streamData.server;
      this.subtitles = streamData.subtitles || [];

      this._setState('LOADING');

      var video = this.videoElement;
      if (!video && typeof document !== 'undefined') {
        video = document.getElementById('main-video-player');
        this.video = video;
        this.videoElement = video;
      }
      if (!video) {
        throw new Error('Video element not found in DOM');
      }

      this._bindVideoElementListeners(video);

      // Ingest external WebVTT subtitle tracks into DOM
      this._ingestSubtitles(video, this.subtitles);

      var HlsClass = (typeof window !== 'undefined' && window.Hls) ? window.Hls : (typeof Hls !== 'undefined' ? Hls : null);
      var isHlsSupported = !!(HlsClass && typeof HlsClass.isSupported === 'function' && HlsClass.isSupported());

      if (isHlsSupported) {
        this.hls = new HlsClass(HLS_WEBOS_CONFIG);
        this._bindHlsListeners(this.hls);
        this.hls.attachMedia(video);
        this.hls.loadSource(streamData.streamUrl);
      } else {
        // Native HLS / MP4 Fallback
        video.src = streamData.streamUrl;
        try { video.load(); } catch (_) {}
      }

      if (global.PlayerOSDController) {
        global.PlayerOSDController.setContentInfo({
          title: this.currentItem ? (this.currentItem.title || this.currentItem.name) : 'Title',
          season: this.currentItem ? this.currentItem.season : null,
          episode: this.currentItem ? this.currentItem.episode : null,
          format: 'HLS fMP4',
          server: this.activeServer
        });
      }

      return Promise.resolve();
    },

    /**
     * Bind listeners to HTMLMediaElement.
     */
    _bindVideoElementListeners: function (video) {
      var self = this;
      if (!video) return;

      this._unbindVideoListeners(video);

      var onPlay = function () {
        self._setState('PLAYING');
        self._startResumeTracking();
        self.emit('play', { currentTime: video.currentTime });
        if (global.PlayerOSDController) global.PlayerOSDController.setPlayState(true);
      };

      var onPause = function () {
        if (self.state !== 'ENDED' && self.state !== 'IDLE') {
          self._setState('PAUSED');
        }
        self.savePlaybackPosition();
        self.emit('pause', { currentTime: video.currentTime });
        if (global.PlayerOSDController) global.PlayerOSDController.setPlayState(false);
      };

      var onTimeUpdate = function () {
        self.currentTime = video.currentTime || 0;
        self.duration = video.duration || 0;
        var percentage = self.duration > 0 ? (self.currentTime / self.duration) * 100 : 0;

        self.emit('timeupdate', {
          currentTime: self.currentTime,
          duration: self.duration,
          percentage: percentage
        });

        if (global.PlayerOSDController) {
          global.PlayerOSDController.updateTimeline(self.currentTime, self.duration, self.bufferedTime);
        }
      };

      var onProgress = function () {
        if (video.buffered && video.buffered.length > 0) {
          var cur = video.currentTime || 0;
          var end = 0;
          for (var i = 0; i < video.buffered.length; i++) {
            if (video.buffered.start(i) <= cur && cur <= video.buffered.end(i)) {
              end = video.buffered.end(i);
              break;
            }
          }
          if (end === 0 && video.buffered.length > 0) {
            end = video.buffered.end(video.buffered.length - 1);
          }
          self.bufferedTime = end;
          var pct = self.duration > 0 ? (end / self.duration) * 100 : 0;
          self.emit('buffered', { bufferedSeconds: end, percentage: pct });
          if (global.PlayerOSDController) {
            global.PlayerOSDController.updateTimeline(self.currentTime, self.duration, end);
          }
        }
      };

      var onWaiting = function () {
        self.isBuffering = true;
        self.emit('buffering', { isBuffering: true });
        if (global.PlayerOSDController) global.PlayerOSDController.setBuffering(true);
      };

      var onPlaying = function () {
        self.isBuffering = false;
        self._clearStreamWatchdog();
        self.emit('buffering', { isBuffering: false });
        if (global.PlayerOSDController) global.PlayerOSDController.setBuffering(false);
      };

      var onCanPlay = function () {
        self._clearStreamWatchdog();
        self.isBuffering = false;
        if (self.state === 'LOADING' || self.state === 'RESOLVING') {
          self._setState('READY');
        }
        if (global.PlayerOSDController) global.PlayerOSDController.setBuffering(false);

        // Apply resume position if pending
        if (self._targetResumeTime !== null && self._targetResumeTime > 10) {
          var target = self._targetResumeTime;
          self._targetResumeTime = null;
          try {
            video.currentTime = target;
          } catch (_) {}
        }
      };

      var onEnded = function () {
        self._setState('ENDED');
        self._clearResumeRecord(self.currentItem);
        self.emit('ended', {});
        if (global.PlayerOSDController) {
          global.PlayerOSDController.setPlayState(false);
          global.PlayerOSDController.showHUD();
        }
      };

      var onError = function (e) {
        console.warn('[PlayerController] Native video element error event:', e);
        var mediaError = video.error;
        var code = mediaError ? mediaError.code : 4;
        var msg = mediaError ? mediaError.message : 'Video playback error';
        self.handleFatalError('MEDIA_ELEMENT_ERROR_' + code, msg);
      };

      this._videoListeners = {
        play: onPlay,
        pause: onPause,
        timeupdate: onTimeUpdate,
        progress: onProgress,
        waiting: onWaiting,
        playing: onPlaying,
        canplay: onCanPlay,
        ended: onEnded,
        error: onError
      };

      for (var evt in this._videoListeners) {
        video.addEventListener(evt, this._videoListeners[evt]);
      }
    },

    /**
     * Unbind listeners from HTMLMediaElement.
     */
    _unbindVideoListeners: function (video) {
      if (!video || !this._videoListeners) return;
      for (var evt in this._videoListeners) {
        video.removeEventListener(evt, this._videoListeners[evt]);
      }
      this._videoListeners = {};
    },

    /**
     * Bind listeners to Hls.js instance.
     */
    _bindHlsListeners: function (hls) {
      var self = this;
      var HlsClass = (typeof window !== 'undefined' && window.Hls) ? window.Hls : (typeof Hls !== 'undefined' ? Hls : null);
      if (!HlsClass || !HlsClass.Events) return;

      hls.on(HlsClass.Events.MANIFEST_PARSED, function (event, data) {
        self._clearStreamWatchdog();
        self._setState('READY');

        // Extract Quality Levels
        self.qualityLevels = [{ index: -1, label: 'Auto (Recommended)', height: 0, width: 0, bitrate: 0, active: true }];
        if (Array.isArray(hls.levels)) {
          hls.levels.forEach(function (lvl, idx) {
            self.qualityLevels.push({
              index: idx,
              label: lvl.name || (lvl.height ? (lvl.height + 'p') : ('Rung ' + idx)),
              height: lvl.height || 0,
              width: lvl.width || 0,
              bitrate: lvl.bitrate || 0,
              active: false
            });
          });
        }

        // Apply resume position if pending
        if (self._targetResumeTime !== null && self._targetResumeTime > 10) {
          var target = self._targetResumeTime;
          self._targetResumeTime = null;
          if (self.videoElement) {
            try { self.videoElement.currentTime = target; } catch (_) {}
          }
        }

        self.emit('ready', {
          duration: self.videoElement ? self.videoElement.duration : 0,
          levels: self.qualityLevels,
          subtitles: self.subtitleTracks
        });

        // Autoplay
        self.play().catch(function (_) {});
      });

      hls.on(HlsClass.Events.LEVEL_SWITCHED, function (event, data) {
        var lvlIndex = data.level;
        self.qualityLevels.forEach(function (q) { q.active = (q.index === lvlIndex); });
        self.emit('qualitychange', { levelIndex: lvlIndex, level: self.qualityLevels.find(function (q) { return q.index === lvlIndex; }) });
      });

      hls.on(HlsClass.Events.ERROR, function (event, data) {
        console.warn('[PlayerController] Hls.js error:', data.type, data.details, 'fatal:', data.fatal);
        if (data.fatal) {
          switch (data.type) {
            case HlsClass.ErrorTypes.NETWORK_ERROR:
              console.warn('[PlayerController] Fatal network error encountered, attempting recovery...');
              try { hls.startLoad(); } catch (_) {}
              break;
            case HlsClass.ErrorTypes.MEDIA_ERROR:
              console.warn('[PlayerController] Fatal media error encountered, recovering...');
              try { hls.recoverMediaError(); } catch (_) {}
              break;
            default:
              self.handleFatalError('FATAL_HLS_ERROR', data.details || 'Unrecoverable streaming error');
              break;
          }
        }
      });
    },

    /**
     * Ingest external WebVTT subtitle tracks into DOM.
     */
    _ingestSubtitles: function (videoElement, externalSubs) {
      while (videoElement.firstChild) {
        if (videoElement.firstChild.nodeName === 'TRACK') {
          videoElement.removeChild(videoElement.firstChild);
        } else {
          break;
        }
      }

      this.subtitleTracks = [
        { id: 'off', label: 'Off', language: 'none', isExternal: false, active: true }
      ];

      if (Array.isArray(externalSubs)) {
        var self = this;
        externalSubs.forEach(function (sub, idx) {
          try {
            var trackEl = document.createElement('track');
            trackEl.kind = 'subtitles';
            trackEl.label = sub.label || ('Subtitle ' + (idx + 1));
            trackEl.srclang = sub.srclang || 'en';
            trackEl.src = sub.src;
            trackEl.default = false;
            videoElement.appendChild(trackEl);
          } catch (_) {}

          self.subtitleTracks.push({
            id: 'ext-' + idx,
            label: sub.label || 'English',
            language: sub.srclang || 'en',
            isExternal: true,
            domIndex: idx,
            active: false
          });
        });
      }
    },

    /**
     * Resume video playback.
     */
    play: function () {
      if (this.videoElement) {
        var p = this.videoElement.play();
        if (p && typeof p.then === 'function') {
          return p;
        }
      }
      return Promise.resolve();
    },

    /**
     * Pause video playback.
     */
    pause: function () {
      if (this.videoElement) {
        try {
          this.videoElement.pause();
        } catch (_) {}
      }
    },

    /**
     * Toggle play/pause state.
     */
    togglePlayPause: function () {
      if (this.isPlaying()) {
        this.pause();
      } else {
        this.play().catch(function (_) {});
      }
    },

    /**
     * Relative seek by delta seconds with bounds clamping.
     */
    seek: function (deltaSeconds) {
      if (!this.videoElement) return;
      var cur = this.videoElement.currentTime || 0;
      var dur = this.videoElement.duration || Infinity;
      var target = Math.max(0, Math.min(dur, cur + deltaSeconds));
      this.videoElement.currentTime = target;
      this.savePlaybackPosition();
    },

    // Alias for seek
    seekBy: function (deltaSeconds) {
      this.seek(deltaSeconds);
    },

    /**
     * Seek directly to absolute timestamp in seconds.
     */
    seekTo: function (absoluteSeconds) {
      if (!this.videoElement) return;
      var dur = this.videoElement.duration || Infinity;
      var target = Math.max(0, Math.min(dur, absoluteSeconds || 0));
      this.videoElement.currentTime = target;
      this.savePlaybackPosition();
    },

    /**
     * Return available quality levels.
     */
    getQualityLevels: function () {
      return this.qualityLevels || [];
    },

    /**
     * Switch video bitrate quality level.
     */
    setQualityLevel: function (index) {
      if (this.hls) {
        this.hls.currentLevel = index;
      }
    },

    /**
     * Return audio tracks.
     */
    getAudioTracks: function () {
      if (this.hls && Array.isArray(this.hls.audioTracks)) {
        return this.hls.audioTracks.map(function (t, idx) {
          return {
            index: idx,
            label: t.name || t.lang || ('Audio ' + (idx + 1)),
            language: t.lang || 'en',
            default: !!t.default,
            active: (self.hls.audioTrack === idx)
          };
        });
      }
      return [];
    },

    /**
     * Set active audio track by index.
     */
    setAudioTrack: function (index) {
      if (this.hls) {
        this.hls.audioTrack = index;
      }
    },

    /**
     * Return available subtitle tracks.
     */
    getSubtitleTracks: function () {
      return this.subtitleTracks || [];
    },

    /**
     * Activate subtitle track by ID ('off', 'ext-0', etc.).
     */
    setSubtitleTrack: function (trackId) {
      var video = this.videoElement;
      if (video && video.textTracks) {
        for (var i = 0; i < video.textTracks.length; i++) {
          video.textTracks[i].mode = 'disabled';
        }
      }

      if (this.hls && this.hls.subtitleTrack !== -1) {
        this.hls.subtitleTrack = -1;
      }

      var self = this;
      this.subtitleTracks.forEach(function (t) {
        t.active = (t.id === trackId);
      });

      if (trackId === 'off') {
        this.emit('subtitlechange', { trackId: 'off', track: this.subtitleTracks[0] });
        return;
      }

      var found = this.subtitleTracks.find(function (t) { return t.id === trackId; });
      if (!found) return;

      if (found.isExternal && video && video.textTracks && video.textTracks[found.domIndex]) {
        video.textTracks[found.domIndex].mode = 'showing';
      } else if (found.hlsIndex !== undefined && this.hls) {
        this.hls.subtitleTrack = found.hlsIndex;
      }

      this.emit('subtitlechange', { trackId: trackId, track: found });
    },

    /**
     * Switch active server cluster node, re-resolving stream while preserving playhead.
     */
    switchServer: function (serverName) {
      var self = this;
      var curTime = this.videoElement ? this.videoElement.currentTime : (this.currentTime || 0);
      this.activeServer = serverName;

      if (global.PlayerOSDController) {
        global.PlayerOSDController.setBuffering(true, 'Switching server to ' + serverName + '...');
      }

      this.emit('serverchange', { server: serverName });

      if (!this.currentItem) {
        return Promise.resolve();
      }

      return this.loadStream(this.currentItem, serverName).then(function () {
        if (curTime > 0) {
          self._targetResumeTime = curTime;
          if (self.videoElement) {
            try { self.videoElement.currentTime = curTime; } catch (_) {}
          }
        }
      });
    },

    /**
     * Retry stream playback after error.
     */
    retry: function () {
      if (!this.currentItem) return Promise.resolve();
      return this.loadStream(this.currentItem, this.activeServer);
    },

    /**
     * Stop active HLS instance and video playback pipeline.
     */
    _stopPlaybackPipeline: function () {
      if (this.hls) {
        try {
          this.hls.stopLoad();
          this.hls.detachMedia();
          this.hls.destroy();
        } catch (_) {}
        this.hls = null;
      }
      if (this.videoElement) {
        try { this.videoElement.pause(); } catch (_) {}
      }
    },

    /**
     * 5-STAGE DETERMINISTIC TEARDOWN PROTOCOL (Memory Safety for 1.5GB webOS TV)
     */
    destroy: function () {
      console.log('[PlayerController] Initiating deterministic 5-stage teardown...');

      // STAGE 1: Cancel all timers & interval tasks
      if (this._resumeSaveTimer) {
        clearInterval(this._resumeSaveTimer);
        this._resumeSaveTimer = null;
      }
      this._clearStreamWatchdog();
      if (this._abortController) {
        try { this._abortController.abort(); } catch (_) {}
        this._abortController = null;
      }

      // Persist final position before destroying
      this.savePlaybackPosition();

      // STAGE 2: Unbind all video element DOM listeners & pause
      if (this.videoElement) {
        this._unbindVideoListeners(this.videoElement);
        try { this.videoElement.pause(); } catch (_) {}
      }

      // STAGE 3: Teardown and destroy Hls.js instance
      if (this.hls) {
        try {
          this.hls.stopLoad();
          this.hls.detachMedia();
          this.hls.destroy();
        } catch (err) {
          console.warn('[PlayerController] Error destroying Hls:', err);
        }
        this.hls = null;
      }

      // STAGE 4: Hardware Video Decoder (VDEC) Context Release
      if (this.videoElement) {
        while (this.videoElement.firstChild) {
          this.videoElement.removeChild(this.videoElement.firstChild);
        }
        this.videoElement.removeAttribute('src');
        this.videoElement.srcObject = null;

        // Force Chromium to flush decoder contexts
        try {
          this.videoElement.load();
        } catch (_) {}
      }

      // STAGE 5: State Machine & Metric Reset
      var prev = this.state;
      this.state = 'IDLE';
      this.currentItem = null;
      this.streamUrl = null;
      this.activeServer = 'secret';
      this.qualityLevels = [];
      this.audioTracks = [];
      this.subtitleTracks = [];
      this.subtitles = [];
      this.duration = 0;
      this.currentTime = 0;
      this.bufferedTime = 0;
      this.isBuffering = false;
      this._targetResumeTime = null;

      if (global.PlayerOSDController && typeof global.PlayerOSDController.destroy === 'function') {
        global.PlayerOSDController.destroy();
      }

      this.emit('statechange', { state: 'IDLE', previousState: prev });
      console.log('[PlayerController] Teardown complete. Memory and decoder freed.');
    },

    /**
     * Handle fatal stream or playback error.
     */
    handleFatalError: function (code, message) {
      this._clearStreamWatchdog();
      this._setState('ERROR');
      this.emit('error', {
        code: code || 'FATAL_ERROR',
        message: message || 'Playback connection error',
        fatal: true,
        server: this.activeServer
      });
      if (global.PlayerOSDController) {
        global.PlayerOSDController.showError('Playback Connection Error', message || 'Failed to load video stream.', {
          code: code,
          server: this.activeServer
        });
      }
    },

    _clearStreamWatchdog: function () {
      if (this._streamTimeoutTimer) {
        clearTimeout(this._streamTimeoutTimer);
        this._streamTimeoutTimer = null;
      }
    },

    _startResumeTracking: function () {
      if (this._resumeSaveTimer) return;
      var self = this;
      this._resumeSaveTimer = setInterval(function () {
        if (self.state === 'PLAYING') {
          self.savePlaybackPosition();
        }
      }, 5000);
    },

    /**
     * Save playback position to localStorage.
     */
    savePlaybackPosition: function () {
      if (!this.currentItem || !this.videoElement) return;
      var pos = this.videoElement.currentTime || this.currentTime || 0;
      var dur = this.videoElement.duration || this.duration || 0;
      if (pos <= 0) return;

      var tmdbId = this.currentItem.tmdbId || this.currentItem.id;
      var type = (this.currentItem.type === 'tv' || this.currentItem.media_type === 'tv') ? 'tv' : 'movie';
      var season = this.currentItem.season || 0;
      var episode = this.currentItem.episode || 0;

      var record = {
        tmdbId: tmdbId,
        type: type,
        season: season,
        episode: episode,
        title: this.currentItem.title || this.currentItem.name || '',
        position: pos,
        duration: dur,
        percentage: dur > 0 ? (pos / dur) * 100 : 0,
        updated: Date.now()
      };

      try {
        var json = JSON.stringify(record);
        if (type === 'tv') {
          var keyTv = 'cinejoy_playback_' + tmdbId + '_tv_' + (season || 1) + '_' + (episode || 1);
          localStorage.setItem(keyTv, json);
        } else {
          // Store under both patterns so all test and consumer variants match
          localStorage.setItem('cinejoy_playback_' + tmdbId + '_movie', json);
          localStorage.setItem('cinejoy_playback_' + tmdbId + '_movie_0_0', json);
        }
      } catch (_) {}
    },

    _getSavedResumeRecord: function (item) {
      if (!item) return null;
      var tmdbId = item.tmdbId || item.id;
      var type = (item.type === 'tv' || item.media_type === 'tv') ? 'tv' : 'movie';
      var season = item.season || 1;
      var episode = item.episode || 1;

      try {
        var raw = null;
        if (type === 'tv') {
          raw = localStorage.getItem('cinejoy_playback_' + tmdbId + '_tv_' + season + '_' + episode);
        } else {
          raw = localStorage.getItem('cinejoy_playback_' + tmdbId + '_movie') ||
                localStorage.getItem('cinejoy_playback_' + tmdbId + '_movie_0_0');
        }
        if (raw) {
          var rec = JSON.parse(raw);
          if (rec && typeof rec.position === 'number') {
            return rec;
          }
        }
      } catch (_) {}
      return null;
    },

    _clearResumeRecord: function (item) {
      if (!item) return;
      var tmdbId = item.tmdbId || item.id;
      var type = (item.type === 'tv' || item.media_type === 'tv') ? 'tv' : 'movie';
      try {
        if (type === 'tv') {
          var s = item.season || 1;
          var e = item.episode || 1;
          localStorage.removeItem('cinejoy_playback_' + tmdbId + '_tv_' + s + '_' + e);
        } else {
          localStorage.removeItem('cinejoy_playback_' + tmdbId + '_movie');
          localStorage.removeItem('cinejoy_playback_' + tmdbId + '_movie_0_0');
        }
      } catch (_) {}
    },

    getState: function () {
      return this.state;
    },

    isPlaying: function () {
      return this.state === 'PLAYING' || (this.videoElement && !this.videoElement.paused && !this.videoElement.ended);
    },

    getCurrentTime: function () {
      return this.videoElement ? (this.videoElement.currentTime || 0) : this.currentTime;
    },

    getDuration: function () {
      return this.videoElement ? (this.videoElement.duration || 0) : this.duration;
    },

    getBuffered: function () {
      return this.bufferedTime;
    },

    getStateData: function () {
      return {
        state: this.state,
        currentTime: this.getCurrentTime(),
        duration: this.getDuration(),
        buffered: this.getBuffered(),
        percentage: this.duration > 0 ? (this.currentTime / this.duration) * 100 : 0,
        server: this.activeServer,
        title: this.currentItem ? (this.currentItem.title || this.currentItem.name || '') : '',
        quality: this.qualityLevels.find(function (q) { return q.active; })?.label || 'Auto'
      };
    },

    activate: function (itemPayload) {
      this.init();
      if (itemPayload) {
        this.loadStream(itemPayload);
      }
    },

    deactivate: function () {
      this.destroy();
    }
  };

  // ===========================================================================
  // 3. PlayerOSDController (10-Foot Television User Interface)
  // ===========================================================================

  var PlayerOSDController = {
    initialized: false,
    _idleTimer: null,
    _cursorTimer: null,
    _toastTimer: null,
    _dom: {},
    _activeModal: null,

    init: function (options) {
      if (this.initialized) return;
      this.initialized = true;

      this._cacheDom();
      this._bindUserInteractions();
      this._bindRemoteKeyHandler();

      console.log('[PlayerOSDController] Initialized 10-foot TV HUD');
    },

    _cacheDom: function () {
      if (typeof document === 'undefined') return;

      this._dom = {
        viewPlayer: document.getElementById('view-player'),
        playerContainer: document.getElementById('player-container'),
        osd: document.getElementById('player-osd'),
        title: document.getElementById('osd-title'),
        metaEpisode: document.getElementById('osd-meta-episode'),
        badgeFormat: document.getElementById('osd-badge-format'),
        badgeServer: document.getElementById('osd-badge-server'),
        currentTime: document.getElementById('osd-current-time'),
        durationTime: document.getElementById('osd-duration-time'),
        scrubber: document.getElementById('osd-scrubber'),
        progressFill: document.getElementById('osd-progress-fill'),
        bufferFill: document.getElementById('osd-buffer-fill'),
        scrubThumb: document.getElementById('osd-scrub-thumb'),
        rewindBtn: document.getElementById('osd-rewind-btn'),
        playBtn: document.getElementById('osd-play-btn'),
        playIcon: document.getElementById('osd-play-icon'),
        forwardBtn: document.getElementById('osd-forward-btn'),
        subtitlesBtn: document.getElementById('osd-subtitles-btn'),
        subtitlesLabel: document.getElementById('osd-subtitles-label'),
        serverBtn: document.getElementById('osd-server-btn'),
        serverLabel: document.getElementById('osd-server-label'),
        buffering: document.getElementById('player-buffering'),
        bufferingText: document.getElementById('player-buffering-text'),
        errorDialog: document.getElementById('player-error-dialog'),
        errorTitle: document.getElementById('player-error-title'),
        errorMessage: document.getElementById('player-error-message'),
        errorRetryBtn: document.getElementById('player-error-retry-btn'),
        errorSwitchBtn: document.getElementById('player-error-switch-btn'),
        errorExitBtn: document.getElementById('player-error-exit-btn'),
        subsModal: document.getElementById('player-subtitles-modal'),
        subsList: document.getElementById('player-subtitles-list'),
        subsCloseBtn: document.getElementById('player-subtitles-close-btn'),
        serverModal: document.getElementById('player-server-modal'),
        serverList: document.getElementById('player-server-list'),
        serverCloseBtn: document.getElementById('player-server-close-btn'),
        feedbackToast: document.getElementById('player-feedback-toast'),
        feedbackText: document.getElementById('player-feedback-text'),
        feedbackIcon: document.getElementById('player-feedback-icon')
      };
    },

    _bindUserInteractions: function () {
      var self = this;
      var d = this._dom;

      // Play/Pause button
      if (d.playBtn) {
        d.playBtn.addEventListener('click', function (e) {
          e.preventDefault();
          PlayerController.togglePlayPause();
          self.resetIdleTimer();
        });
      }

      // Rewind 10s
      if (d.rewindBtn) {
        d.rewindBtn.addEventListener('click', function (e) {
          e.preventDefault();
          PlayerController.seek(-10);
          self.showSeekFeedback(false, 10);
          self.resetIdleTimer();
        });
      }

      // Forward 10s
      if (d.forwardBtn) {
        d.forwardBtn.addEventListener('click', function (e) {
          e.preventDefault();
          PlayerController.seek(10);
          self.showSeekFeedback(true, 10);
          self.resetIdleTimer();
        });
      }

      // Subtitles modal trigger
      if (d.subtitlesBtn) {
        d.subtitlesBtn.addEventListener('click', function (e) {
          e.preventDefault();
          self.openSubtitlesModal();
        });
      }

      // Server modal trigger
      if (d.serverBtn) {
        d.serverBtn.addEventListener('click', function (e) {
          e.preventDefault();
          self.openServerModal();
        });
      }

      // Subtitle close
      if (d.subsCloseBtn) {
        d.subsCloseBtn.addEventListener('click', function (e) {
          e.preventDefault();
          self.closeActiveModal();
        });
      }

      // Server close
      if (d.serverCloseBtn) {
        d.serverCloseBtn.addEventListener('click', function (e) {
          e.preventDefault();
          self.closeActiveModal();
        });
      }

      // Error retry
      if (d.errorRetryBtn) {
        d.errorRetryBtn.addEventListener('click', function (e) {
          e.preventDefault();
          self.closeActiveModal();
          PlayerController.retry();
        });
      }

      // Error switch server
      if (d.errorSwitchBtn) {
        d.errorSwitchBtn.addEventListener('click', function (e) {
          e.preventDefault();
          self.closeActiveModal();
          self.openServerModal();
        });
      }

      // Error exit to details
      if (d.errorExitBtn) {
        d.errorExitBtn.addEventListener('click', function (e) {
          e.preventDefault();
          self.closeActiveModal();
          if (global.CinejoyApp) {
            global.CinejoyApp.exitPlayer();
          }
        });
      }

      // Mouse movements wake cursor & OSD
      if (d.playerContainer) {
        d.playerContainer.addEventListener('mousemove', function () {
          d.playerContainer.classList.remove('idle-cursor');
          self.showHUD();
          if (self._cursorTimer) clearTimeout(self._cursorTimer);
          self._cursorTimer = setTimeout(function () {
            d.playerContainer.classList.add('idle-cursor');
          }, 2000);
        });
      }
    },

    _bindRemoteKeyHandler: function () {
      var self = this;
      if (typeof window === 'undefined') return;

      this._keydownHandler = function (e) {
        self._onKeyDown(e);
      };
      window.addEventListener('keydown', this._keydownHandler);
    },

    _onKeyDown: function (e) {
      if (!this._dom.viewPlayer || !this._dom.viewPlayer.classList.contains('active')) {
        return;
      }

      var code = e.keyCode || e.which;

      // 1. Back Key (461 / 27)
      if (code === 461 || code === 27 || e.key === 'Escape') {
        if (this._activeModal) {
          if (e.preventDefault) e.preventDefault();
          if (e.stopPropagation) e.stopPropagation();
          this.closeActiveModal();
          return;
        }
        if (e.preventDefault) e.preventDefault();
        if (e.stopPropagation) e.stopPropagation();
        if (global.CinejoyApp) {
          global.CinejoyApp.exitPlayer();
        }
        return;
      }

      // 2. Stop Key (413 / 178)
      if (code === 413 || code === 178) {
        if (e.preventDefault) e.preventDefault();
        if (this._activeModal) this.closeActiveModal();
        if (global.CinejoyApp) global.CinejoyApp.exitPlayer();
        return;
      }

      // 3. Media Play (415)
      if (code === 415) {
        if (e.preventDefault) e.preventDefault();
        PlayerController.play();
        this.resetIdleTimer();
        return;
      }

      // 4. Media Pause (19)
      if (code === 19) {
        if (e.preventDefault) e.preventDefault();
        PlayerController.pause();
        this.showHUD();
        return;
      }

      // 5. Media Play/Pause (179)
      if (code === 179 && e.key !== 'MediaPlay') {
        if (e.preventDefault) e.preventDefault();
        PlayerController.togglePlayPause();
        return;
      }

      // 6. Fast Forward (417 / 228)
      if (code === 417 || code === 228) {
        if (e.preventDefault) e.preventDefault();
        PlayerController.seek(10);
        this.showSeekFeedback(true, 10);
        this.resetIdleTimer();
        return;
      }

      // 7. Rewind (412 / 227)
      if (code === 412 || code === 227) {
        if (e.preventDefault) e.preventDefault();
        PlayerController.seek(-10);
        this.showSeekFeedback(false, 10);
        this.resetIdleTimer();
        return;
      }

      // 8. If Modal Active, let SpatialNav trap handle it
      if (this._activeModal) {
        return;
      }

      var isHudHidden = this._dom.osd && this._dom.osd.classList.contains('osd-hidden');

      // 9. D-Pad Left (37)
      if (code === 37 || e.key === 'ArrowLeft') {
        if (isHudHidden) {
          if (e.preventDefault) e.preventDefault();
          PlayerController.seek(-10);
          this.showSeekFeedback(false, 10);
          this.showHUD();
          return;
        } else {
          var curFocus = (global.SpatialNav && global.SpatialNav.getCurrentFocus()) || document.activeElement;
          if (curFocus === this._dom.scrubber) {
            if (e.preventDefault) e.preventDefault();
            PlayerController.seek(-10);
            this.showSeekFeedback(false, 10);
            this.resetIdleTimer();
            return;
          }
          this.resetIdleTimer();
        }
      }

      // 10. D-Pad Right (39)
      if (code === 39 || e.key === 'ArrowRight') {
        if (isHudHidden) {
          if (e.preventDefault) e.preventDefault();
          PlayerController.seek(10);
          this.showSeekFeedback(true, 10);
          this.showHUD();
