      assert(rect.right <= 1824, `Button ${btn.id} right (${rect.right}) > 1824px`);
      assert(rect.top >= 54, `Button ${btn.id} top (${rect.top}) < 54px`);
      assert(rect.bottom <= 1026, `Button ${btn.id} bottom (${rect.bottom}) > 1026px`);
