  // ===========================================================================
  // SUITE 4: Remote Control Keybindings Suite (8 Checks)
  // ===========================================================================
  console.log(`\n${C.bold}▶ SUITE 4: Remote Control Keybindings Suite${C.reset}`);

  await check('S4', '1', 'Enter / OK Remote Key (13) Play/Pause Toggle', async () => {
    const harness = createM5Harness();
