  await check('S4', '3', 'D-Pad Right Key (39) Forward Seeking (+10s)', async () => {
    const harness = createM5Harness();
    harness.app.switchView('player');
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
    harness.video.currentTime = 50;
