    harness.window.dispatchEvent(new harness.window.KeyboardEvent('keydown', { keyCode: 39, key: 'ArrowRight' }));
    assert.strictEqual(harness.video.currentTime, 60);

    const toast = harness.window.document.getElementById('player-feedback-toast');
    assert.strictEqual(toast.style.display, 'flex');
  });

  await check('S4', '4', 'D-Pad Up / Down Keys (38/40) HUD Wakeup & Focus', async () => {
    const harness = createM5Harness();
    harness.app.switchView('player');
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
    harness.osd.hideHUD();
