    assert(osdEl.classList.contains('osd-hidden'));

    harness.window.dispatchEvent(new harness.window.KeyboardEvent('keydown', { keyCode: 40, key: 'ArrowDown' }));
    assert(!osdEl.classList.contains('osd-hidden'));
    const curFocus = harness.nav.getCurrentFocus();
    assert(curFocus && curFocus.id === 'osd-play-btn', 'Focus should be on #osd-play-btn');
  });

  await check('S4', '5', 'WebOS Remote Back Key (461 / 27) Teardown & Return', async () => {
    const harness = createM5Harness();
    harness.app.switchView('details', { tmdbId: 693134, title: 'Dune: Part Two' });
    harness.app.switchView('player', { tmdbId: 693134, title: 'Dune: Part Two' });
    assert.strictEqual(harness.app.state.currentView, 'player');

    harness.window.dispatchEvent(new harness.window.KeyboardEvent('keydown', { keyCode: 461, key: 'Back' }));
    assert.strictEqual(harness.app.state.currentView, 'details');
    assert.strictEqual(harness.player.state, 'IDLE', 'Player should be destroyed');
  });

  await check('S4', '6', 'WebOS Media Play / Pause / PlayPause / Stop Keys', async () => {
    const harness = createM5Harness();
    harness.app.switchView('details');
    harness.app.switchView('player');
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });

    // 415 play
    harness.window.dispatchEvent(new harness.window.KeyboardEvent('keydown', { keyCode: 415, key: 'MediaPlay' }));
    assert.strictEqual(harness.video.paused, false);

    // 19 pause
    harness.window.dispatchEvent(new harness.window.KeyboardEvent('keydown', { keyCode: 19, key: 'MediaPause' }));
    assert.strictEqual(harness.video.paused, true);

    // 179 toggle
    harness.window.dispatchEvent(new harness.window.KeyboardEvent('keydown', { keyCode: 179, key: 'MediaPlayPause' }));
    assert.strictEqual(harness.video.paused, false);

    // 413 stop -> exit to details
    harness.window.dispatchEvent(new harness.window.KeyboardEvent('keydown', { keyCode: 413, key: 'MediaStop' }));
    assert.strictEqual(harness.app.state.currentView, 'details');
  });

  await check('S4', '7', 'WebOS Media FastForward (417) & Rewind (412) Keys', async () => {
    const harness = createM5Harness();
    harness.app.switchView('player');
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
    harness.video.currentTime = 50;

    harness.window.dispatchEvent(new harness.window.KeyboardEvent('keydown', { keyCode: 417, key: 'MediaFastForward' }));
    assert.strictEqual(harness.video.currentTime, 60);

    harness.window.dispatchEvent(new harness.window.KeyboardEvent('keydown', { keyCode: 412, key: 'MediaRewind' }));
    assert.strictEqual(harness.video.currentTime, 50);
  });

  await check('S4', '8', 'Spatial D-Pad Navigation Sequence Across Controls', async () => {
    const harness = createM5Harness();
    harness.app.switchView('player');
    const rewindBtn = harness.window.document.getElementById('osd-rewind-btn');
    const playBtn = harness.window.document.getElementById('osd-play-btn');
    const forwardBtn = harness.window.document.getElementById('osd-forward-btn');
    const subBtn = harness.window.document.getElementById('osd-subtitles-btn');
    const srvBtn = harness.window.document.getElementById('osd-server-btn');

    harness.nav.setFocus(rewindBtn);
    assert.strictEqual(harness.nav.getCurrentFocus(), rewindBtn);

    harness.nav.move('right');
    assert.strictEqual(harness.nav.getCurrentFocus(), playBtn);

    harness.nav.move('right');
    assert.strictEqual(harness.nav.getCurrentFocus(), forwardBtn);

    harness.nav.move('right');
    assert.strictEqual(harness.nav.getCurrentFocus(), subBtn);

    harness.nav.move('right');
    assert.strictEqual(harness.nav.getCurrentFocus(), srvBtn);
  });

  // ===========================================================================
  // SUITE 5: Subtitle & Server Switching Suite (7 Checks)
  // ===========================================================================
  console.log(`\n${C.bold}▶ SUITE 5: Subtitle & Server Switching Suite${C.reset}`);

  await check('S5', '1', 'Subtitle Modal Generation from Ingested Tracks', async () => {
    const harness = createM5Harness();
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
    harness.osd.openSubtitlesModal();

    const list = harness.window.document.getElementById('player-subtitles-list');
    const items = list.querySelectorAll('.modal-list-item');
    assert(items.length >= 3, 'Expected at least 3 subtitle items (Off, English, Spanish), got ' + items.length);
    assert(items[0].textContent.includes('Off'));
    assert(items[1].textContent.includes('English'));
    assert(items[0].classList.contains('active'), 'Off should be active initially');
  });

  await check('S5', '2', 'Subtitle Modal Focus Trapping with SpatialNav.trap', async () => {
    const harness = createM5Harness();
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
    harness.osd.openSubtitlesModal();

    assert(harness.nav.isTrapped(), 'SpatialNav should be trapped');
    const cur = harness.nav.getCurrentFocus();
    assert(cur && cur.closest('#player-subtitles-modal'), 'Focus should be inside modal');
  });

  await check('S5', '3', 'Subtitle Track Selection & WebVTT Mode Activation', async () => {
    const harness = createM5Harness();
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
    harness.osd.openSubtitlesModal();

    const list = harness.window.document.getElementById('player-subtitles-list');
    const items = list.querySelectorAll('.modal-list-item');
    items[1].click(); // Click English

    assert.strictEqual(harness.video.textTracks[0].mode, 'showing');
    const subLabel = harness.window.document.getElementById('osd-subtitles-label');
    assert(subLabel.textContent.includes('EN') || subLabel.textContent.includes('English'));
    assert.strictEqual(harness.window.document.getElementById('player-subtitles-modal').style.display, 'none');
  });

  await check('S5', '4', 'Subtitle Track Disable ("Off") Selection', async () => {
    const harness = createM5Harness();
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
    harness.osd.openSubtitlesModal();

    const list = harness.window.document.getElementById('player-subtitles-list');
    const items = list.querySelectorAll('.modal-list-item');
    items[0].click(); // Click Off

    assert.strictEqual(harness.video.textTracks[0].mode, 'disabled');
    const subLabel = harness.window.document.getElementById('osd-subtitles-label');
    assert(subLabel.textContent.includes('Off'));
  });

  await check('S5', '5', 'Server Cluster Modal Population from /api/servers', async () => {
    const harness = createM5Harness();
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
    harness.osd.openServerModal();

    const list = harness.window.document.getElementById('player-server-list');
    const items = list.querySelectorAll('.modal-list-item');
    assert.strictEqual(items.length, 5, 'Expected 5 cluster server items');
    assert(items[0].textContent.includes('secret') && items[0].textContent.includes('4K Ultra HD'));
    assert(items[1].textContent.includes('Nebula') && items[1].textContent.includes('1080p HD'));
  });

  await check('S5', '6', 'Server Switch Triggers Stream Re-Resolution', async () => {
    let lastUrl = null;
    const harness = createM5Harness({
      onFetch: (url) => { lastUrl = String(url); }
    });
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
    harness.osd.openServerModal();

    const list = harness.window.document.getElementById('player-server-list');
    const nebulaItem = list.querySelector('[data-server="Nebula"]');
    nebulaItem.click();

