    assert.strictEqual(buf.style.display, 'none');
  });

  await check('S6', '3', '15000ms Stream Startup Timeout Watchdog', async () => {
    const harness = createM5Harness();
    // Start loadMedia without triggering canplay
    harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });

