    assert.strictEqual(errDialog.style.display, 'flex');
  });

  await check('S6', '4', 'Fatal HLS Network Error Triggers Error Recovery Dialog', async () => {
    const harness = createM5Harness();
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });

