    const cur = harness.nav.getCurrentFocus();
    assert(cur && cur.id === 'player-error-retry-btn', 'Focus should be on retry button');
  });

  await check('S6', '5', 'Error Dialog "Retry Playback" Recovery Action', async () => {
    const harness = createM5Harness();
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
    harness.player.handleFatalError('FATAL_ERR', 'Fatal error');

    const retryBtn = harness.window.document.getElementById('player-error-retry-btn');
    retryBtn.click();

    assert.strictEqual(harness.window.document.getElementById('player-error-dialog').style.display, 'none');
    assert.notStrictEqual(harness.player.state, 'ERROR');
  });

  await check('S6', '6', 'Error Dialog "Switch Server" Fallback Action', async () => {
    const harness = createM5Harness();
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
    harness.player.handleFatalError('FATAL_ERR', 'Fatal error');

    const switchBtn = harness.window.document.getElementById('player-error-switch-btn');
    switchBtn.click();

    assert.strictEqual(harness.window.document.getElementById('player-error-dialog').style.display, 'none');
    assert.strictEqual(harness.window.document.getElementById('player-server-modal').style.display, 'flex');
    assert(harness.nav.isTrapped());
  });

  await check('S6', '7', 'Playback Resume Position Persistence to LocalStorage', async () => {
    const harness = createM5Harness();
    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
    harness.video._setDuration(7200);
    harness.video.currentTime = 1420;

    harness.player.destroy();

    const stored = harness.window.localStorage.getItem('cinejoy_playback_693134_movie');
    assert(stored, 'LocalStorage should contain cinejoy_playback_693134_movie');
    const parsed = JSON.parse(stored);
    assert.strictEqual(parsed.position, 1420);
    assert.strictEqual(parsed.duration, 7200);
  });

  await check('S6', '8', 'Playback Resume Position Restoration on Re-load', async () => {
    const harness = createM5Harness();
    harness.window.localStorage.setItem('cinejoy_playback_693134_movie', JSON.stringify({
      position: 1420,
      duration: 7200
    }));

    await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
    assert.strictEqual(harness.video.currentTime, 1420, 'Should restore resume position 1420s');
  });

  // ===========================================================================
  // Summary & Verdict
  // ===========================================================================
  console.log(`\n${C.bold}========================================================================${C.reset}`);
  console.log(`Test Execution Summary:`);
  console.log(`  Total Checks:   ${totalChecks}`);
  console.log(`  Passed Checks:  ${C.green}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:  ${failedChecks > 0 ? C.red : C.green}${failedChecks}${C.reset}`);
  console.log(`${C.bold}========================================================================${C.reset}\n`);

  if (failedChecks > 0) {
    console.log(`${C.red}${C.bold}VERDICT: TEST SUITE FAILED (${failedChecks} failures)${C.reset}\n`);
    process.exit(1);
  } else {
    console.log(`${C.green}${C.bold}VERDICT: ALL ${totalChecks} AUTOMATED VERIFICATION CHECKS PASSED (100% SUCCESS)${C.reset}\n`);
    process.exit(0);
  }
}

runAllSuites().catch(err => {
  console.error('Fatal harness error:', err);
  process.exit(1);
});

