args.ReplacementContent:
hideHUD: function () {
  if (!this._dom.osd) this._cacheDom();
  if (this._activeModal) {
    return; // Inhibit hiding while modal/error dialog is open
  }
  if (this._dom.osd) {
    this._dom.osd.classList.add('osd-hidden');
  }
},

toggleHUD: function () {
  if (!this._dom.osd) this._cacheDom();
  if (this._dom.osd && this._dom.osd.classList.contains('osd-hidden')) {
    this.showHUD();
  } else {
    this.hideHUD();
  }
},

resetIdleTimer: function () {
  if (this._idleTimer) {
    clearTimeout(this._idleTimer);
    this._idleTimer = null;
  }

  var video = PlayerController.videoElement;
  if (video && video.paused) {
    return; // Suspended permanently while paused
  }
  if (this._activeModal) {
    return; // Suspended while modal is open
  }

  var self = this;
  this._idleTimer = setTimeout(function () {
    var vid = PlayerController.videoElement;
    if (vid && vid.paused) return;
    self.hideHUD();
  }, 4000);
},

