await check('S4', '1', 'Enter / OK Remote Key (13) Play/Pause Toggle', async () => {
  const harness = createM5Harness();
  harness.app.switchView('player');
  await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
  await harness.player.play();
  assert.strictEqual(harness.player.isPlaying(), true);

  console.log('[DEBUG S4.1] Focus before Enter:', harness.nav.getCurrentFocus()?.id, 'video.paused:', harness.video.paused);
  // Keydown 13 pauses
  harness.window.dispatchEvent(new harness.window.KeyboardEvent('keydown', { keyCode: 13, key: 'Enter' }));
  console.log('[DEBUG S4.1] Focus after Enter:', harness.nav.getCurrentFocus()?.id, 'video.paused:', harness.video.paused);
  assert.strictEqual(harness.video.paused, true);

  // Keydown 13 resumes
  harness.window.dispatchEvent(new harness.window.KeyboardEvent('keydown', { keyCode: 13, key: 'Enter' }));
  console.log('[DEBUG S4.1] After 2nd Enter video.paused:', harness.video.paused);
  assert.strictEqual(harness.video.paused, false);
});

args.TargetContent:
await check('S4', '1', 'Enter / OK Remote Key (13) Play/Pause Toggle', async () => {
  const harness = createM5Harness();
  harness.app.switchView('player');
  await harness.player.loadMedia({ tmdbId: 693134, type: 'movie' });
  await harness.player.play();
  assert.strictEqual(harness.player.isPlaying(), true);

  // Keydown 13 pauses
  harness.window.dispatchEvent(new harness.window.KeyboardEvent('keydown', { keyCode: 13, key: 'Enter' }));
  assert.strictEqual(harness.video.paused, true);

  // Keydown 13 resumes
  harness.window.dispatchEvent(new harness.window.KeyboardEvent('keydown', { keyCode: 13, key: 'Enter' }));
  assert.strictEqual(harness.video.paused, false);
});

