focusFirstElementInView: function (viewName) {
  if (this.state.currentView !== viewName) return;

  var viewEl = document.getElementById('view-' + viewName);
  if (!viewEl) return;

  if (viewName === 'player') {
    var playBtn = document.getElementById('osd-play-btn');
    if (playBtn) {
      this.setFocus(playBtn);
      return;
    }
  }

  // Do not hijack focus if user already navigated to an element inside this view
  if (this.state.focusedElement && viewEl.contains(this.state.focusedElement)) {
    return;
  }

